import{_ as t,o as a,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy project handbook","description":"Historical November 9 orientation.\\nUse the current start page, lesson-collection GDD, and readiness plan for the new direction.\\nThe economy, restoration, and actual-model requ","frontmatter":{"title":"Chainy project handbook","description":"Historical November 9 orientation.\\nUse the current start page, lesson-collection GDD, and readiness plan for the new direction.\\nThe economy, restoration, and actual-model requ","source":"docs/archive/pre-lesson-collection-2026-11-11/project-handbook.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.md"}'),o={name:"content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.md"};function i(d,e,s,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[r(`<div><h1 id="chainy-project-handbook">Chainy project handbook<a class="header-anchor" href="#chainy-project-handbook" aria-label="Link to this section">​</a></h1><blockquote><p><strong>Historical November 9 orientation.</strong> Use the <a href="/Chainy-Docs/content/docs/documentation-index.html">current start page</a>, <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a>, and <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">readiness plan</a> for the new direction. The economy, restoration, and actual-model requirements in this handbook are superseded. Current work is documentation/setup only, pending final approval to develop.</p></blockquote><p>Prepared November 9, 2026 from the current project documents and a static inspection of the local Unity checkout. This is a single-file orientation guide for understanding the project, its intended gameplay, development setup, and delivery obligations. It summarizes existing decisions without replacing the baseline, canonical game design, or team board.</p><p><strong>The pre-final date is November 21, 2026.</strong> The November 10 Cryptita Plays community session is a gameplay beta only if the November 9 build gate passes. Otherwise, the recorded fallback is a clearly labeled concept/prototype feedback session. This handbook does not establish the outcome of that gate.</p><h2 id="contents">Contents<a class="header-anchor" href="#contents" aria-label="Link to this section">​</a></h2><ol><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#project-at-a-glance">Project at a glance</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#audience-and-learning-purpose">Audience and learning purpose</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#scope-and-implementation-status">Scope and implementation status</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#how-to-play-the-designed-core-chapter">How to play the designed core chapter</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#full-journey-and-curriculum">Full journey and curriculum</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#visuals-interface-and-accessibility">Visuals, interface, and accessibility</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#technology-and-architecture">Technology and architecture</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#local-data-and-offline-operation">Local data and offline operation</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#set-up-and-run-the-game">Set up and run the game</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#documentation-and-team-tools">Documentation and team tools</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#team-responsibilities">Team responsibilities</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#testing-and-acceptance">Testing and acceptance</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#schedule-and-capstone-evidence">Schedule and capstone evidence</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#common-questions-and-troubleshooting">Common questions and troubleshooting</a></li><li><a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-handbook.html#open-decisions-and-source-map">Open decisions and source map</a></li></ol><h2 id="project-at-a-glance">Project at a glance<a class="header-anchor" href="#project-at-a-glance" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Item</th><th>Current position</th></tr></thead><tbody><tr><td>Formal title</td><td>Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</td></tr><tr><td>Product</td><td>Single-player, offline 3D educational adventure</td></tr><tr><td>Target platform</td><td>Android</td></tr><tr><td>Primary audience</td><td>Learners aged 12-17, including communities with limited connectivity</td></tr><tr><td>Initial language</td><td>English</td></tr><tr><td>Subjects</td><td>Web3, Blockchain, and AI</td></tr><tr><td>Core experience</td><td>Explore compact islands, help residents, make fictional transactions, repair records, and receive explanatory feedback</td></tr><tr><td>Engine and language</td><td>Unity and C#</td></tr><tr><td>Local storage</td><td>SQLite</td></tr><tr><td>Camera and art</td><td>Fixed orthographic isometric camera and restrained low-poly environments</td></tr><tr><td>Current gameplay authority</td><td>GDD v2, adopted October 23, 2026</td></tr><tr><td>Management repository</td><td>This repository holds requirements, decisions, documentation, and tooling</td></tr><tr><td>Game source</td><td>Separate Chainy-Game repository and the local ChainyApp Unity checkout</td></tr><tr><td>Current release evidence</td><td>No runtime acceptance was performed for this handbook</td></tr></tbody></table><p>The story follows the Explorer as island services stop working. Sean guides the Web3 harbor, Matthew guides the Blockchain beacon, and Lee guides the AI assistance center. Restoring the workshop, beacon, and supervised helper gives each subject a practical purpose. The same fictional lantern purchase connects the first two worlds and provides context for later AI judgment.</p><p>The game does not require cryptocurrency, real payments, a real wallet, a public blockchain, or cloud AI. Multiplayer, combat, speculative trading, live generative chat, and a procedural open world are outside the adopted version.</p><p>Source basis is the <a href="/Chainy-Docs/content/docs/project-baseline.html">project baseline</a> and <a href="/Chainy-Docs/content/docs/game-design.html">canonical GDD</a>.</p><h2 id="audience-and-learning-purpose">Audience and learning purpose<a class="header-anchor" href="#audience-and-learning-purpose" aria-label="Link to this section">​</a></h2><p>Learners are not expected to have prior cryptocurrency or programming experience. The design introduces an example, lets the player act, explains the result, and then checks understanding in another situation. Short quizzes support the action instead of replacing the adventure with definitions.</p><table><thead><tr><th>User or stakeholder</th><th>What they need from Chainy</th></tr></thead><tbody><tr><td>Learner</td><td>Understandable objectives, safe fictional examples, readable controls, useful feedback, and dependable offline saves</td></tr><tr><td>Session facilitator</td><td>A tested build, consistent instructions, disclosed limitations, and an approved evidence procedure</td></tr><tr><td>Teacher in the later product</td><td>Enrollment, protected access, learner-record collection, and a separate upload workflow</td></tr><tr><td>Development team</td><td>Clear requirements, one owner per card, explicit handoffs, and reproducible build evidence</td></tr><tr><td>Adviser or defense panel</td><td>A working demonstrated scope, accurate manuscript, actual evaluation evidence, and honest limitations</td></tr></tbody></table><p>The full school model anticipates a personal phone for each learner. The beta uses a simple local demo profile. A learner code identifies a local profile; it does not authenticate a person or recover another phone&#39;s records. The five team-board accounts belong to the project team and are unrelated to learner profiles.</p><p>The intended learning outcomes are distinct. Web3 activities teach access, ownership, authorization, payment, and fees. Blockchain activities teach linked records, verification, and the difference between a stale copy and an altered copy. AI activities teach examples, predictions, testing, limitations, and human review.</p><p>Completing a quest, answering after a hint, or filling an encyclopedia entry is not proof of mastery. Independent assessment and repeated practice must remain distinguishable. The <a href="/Chainy-Docs/content/docs/learning-foundations.html">learning foundations</a> and <a href="/Chainy-Docs/content/docs/qa-evaluation.html">evaluation plan</a> explain these boundaries.</p><h2 id="scope-and-implementation-status">Scope and implementation status<a class="header-anchor" href="#scope-and-implementation-status" aria-label="Link to this section">​</a></h2><h3 id="delivery-labels">Delivery labels<a class="header-anchor" href="#delivery-labels" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Label</th><th>Included work</th><th>Meaning</th></tr></thead><tbody><tr><td>CORE</td><td>W01-W04, B01-B03 and demo B07, contextual Quiz, compact exploration/dialogue/UI, quest log, encyclopedia, and reliable SQLite saves</td><td>Required core acceptance boundary</td></tr><tr><td>STRETCH</td><td>A01-A03 with an actual small offline classifier</td><td>Admitted only after core Android checks pass and capacity is approved</td></tr><tr><td>FULL</td><td>W05-W08, B04-B06 and full B07, A04-A05, standalone Wordle and BlockMatch</td><td>Retained full design, not a November 10 promise</td></tr><tr><td>LATER SERVICE</td><td>Teacher activation, offline pairing, protected dashboard, collection, upload, and distribution</td><td>Separate service work, not a beta dependency</td></tr></tbody></table><p>The 26-letter curriculum and 13 AI pairings are full-curriculum directions. They do not expand the November 10 core commitment. The <a href="/Chainy-Docs/content/docs/game-design-simplified-draft.html">simplified GDD draft</a> explicitly remains a proposed replacement pending owner approval. Its badge-based journey does not silently replace the adopted restoration design.</p><h3 id="what-the-evidence-establishes">What the evidence establishes<a class="header-anchor" href="#what-the-evidence-establishes" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Evidence</th><th>What can be said</th><th>What cannot be concluded</th></tr></thead><tbody><tr><td>October reports</td><td>Movement was reported complete; movement and dialogue were later reported playable</td><td>That the complete Android chapter passed</td></tr><tr><td>November 7 local-source review</td><td>SQLite account/content/progress infrastructure exists in the inspected source</td><td>That v2 economic and restoration persistence works</td></tr><tr><td>November 7 owner statement</td><td>The local checkout is the current development source; no candidate APK or revision identifier was supplied then</td><td>That no newer candidate exists on November 9</td></tr><tr><td>November 9 package/config inspection</td><td>The local project declares Unity 6000.3.25f1 and the package versions listed below</td><td>That the project compiles, runs, or meets device acceptance</td></tr><tr><td>GDD, illustrations, and task cards</td><td>Intended behavior, design targets, and recorded work</td><td>Completed gameplay or measured learning results</td></tr></tbody></table><p>The November 7 source assessment found three configured modules, six lessons, no minigames, and one quest. It did not find the v2 wallet, inventory, purchase/fee ledger, reward receipts, restoration, encyclopedia checkpoints, or versioned recovery in inspected first-party scripts. It also recorded risks around switching profiles, updating incomplete lessons, database startup failure, and stale test instructions. These are dated static findings, not a fresh runtime reproduction.</p><p>The live board owns current task status. This handbook does not recalculate completion, change card status, or infer the school&#39;s completion percentage.</p><h2 id="how-to-play-the-designed-core-chapter">How to play the designed core chapter<a class="header-anchor" href="#how-to-play-the-designed-core-chapter" aria-label="Link to this section">​</a></h2><p>This walkthrough describes the approved behavior. Use it as a player explanation and demonstration checklist once a named build implements the chapter. Screen names, button positions, and save feedback still need comparison with the tested build.</p><h3 id="start-and-controls">Start and controls<a class="header-anchor" href="#start-and-controls" aria-label="Link to this section">​</a></h3><ol><li>Open the installed game and select the correct local demo profile.</li><li>Choose Play and enter the available world.</li><li>Follow the current objective to the visible guide or learning station.</li><li>Read the short explanation and perform the requested action.</li><li>Check the result and wait for confirmed save feedback.</li></ol><table><thead><tr><th>Control</th><th>Intended action</th></tr></thead><tbody><tr><td>Left thumb joystick</td><td>Move through the world</td></tr><tr><td>Right contextual button</td><td>Interact with a nearby target</td></tr><tr><td>Dialogue choices</td><td>Answer or choose while world movement is disabled</td></tr><tr><td>Quest log</td><td>Read the current objective, location, and prerequisites</td></tr><tr><td>Encyclopedia</td><td>Revisit a concept and its example</td></tr><tr><td>Select a card, then a destination</td><td>Place or compare a record without requiring dragging</td></tr><tr><td>Back or pause</td><td>Close the current layer or pause without losing a committed action</td></tr></tbody></table><p>The intended camera stays fixed. Jumping, combat, free-camera rotation, and precision platforming are not required. Landscape orientation is the proposed target, not a device-test result.</p><h3 id="web3-harbor-walkthrough">Web3 harbor walkthrough<a class="header-anchor" href="#web3-harbor-walkthrough" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Quest</th><th>What you do</th><th>Expected result</th></tr></thead><tbody><tr><td>W01, arrive and meet Sean</td><td>Find Sean, inspect the quest log and encyclopedia, and view the fictional wallet and receiving address</td><td>Understand the next objective and distinguish shareable information from secrets</td></tr><tr><td>W02, help the resident</td><td>Collect the repair component and return it</td><td>Receive 12 fictional Chain Coins exactly once</td></tr><tr><td>W03, buy the lantern</td><td>Inspect Lantern #014 and review its 8-coin price plus a 1-coin fee</td><td>Confirm a total of 9 and a remaining balance of 3</td></tr><tr><td>W04, light the workshop</td><td>Verify ownership, equip the lantern, and activate the mechanism</td><td>Restore the workshop and save the result</td></tr></tbody></table><p>The purchase review shows the recipient, item, price, fee, and total before authorization. Canceling before submission costs nothing. Repeated taps must not purchase the same lantern twice. Equipping an owned lantern, walking, reading, and viewing balances are free. The 12-coin reward is a game allocation, not a claim that real cryptocurrency comes from errands.</p><p>The wallet displays account information and provides a fictional authorization control. The ownership record belongs to the simulated ledger. No real seed phrase, private key, payment information, or financial account belongs in this activity.</p><h3 id="blockchain-beacon-walkthrough">Blockchain beacon walkthrough<a class="header-anchor" href="#blockchain-beacon-walkthrough" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Quest</th><th>What you do</th><th>Expected result</th></tr></thead><tbody><tr><td>B01, read the familiar record</td><td>Inspect the saved lantern purchase</td><td>Find the original 8-coin price, 1-coin fee, and Lantern #014 transfer</td></tr><tr><td>B02, restore the sequence</td><td>Place three subsequent blocks after a trusted checkpoint</td><td>Previous-block references form a valid sequence</td></tr><tr><td>B03, reject the altered copy</td><td>Compare a damaged 6-coin payment display with the verified 8-coin record</td><td>Identify the mismatch and restore the local copy from the trusted source</td></tr><tr><td>Demo B07, restore the beacon</td><td>Recheck the repaired record and explain the result</td><td>The beacon lights and the demo chapter saves</td></tr></tbody></table><p>Use the references between blocks rather than their colors or timestamps to determine the order. The verified source remains read-only. The activity repairs a damaged local copy; it does not let the learner rewrite accepted history. The simulated nodes are records on one phone, not a network of learner phones. This repair activity is separate from the deferred BlockMatch mini-game.</p><h3 id="mistakes-saving-and-progression">Mistakes, saving, and progression<a class="header-anchor" href="#mistakes-saving-and-progression" aria-label="Link to this section">​</a></h3><p>A wrong answer explains the error and permits another attempt without taking essential resources. An early quest pickup remains recorded. A repeated report must not repeat a reward. Insufficient funds must show what is missing and a valid recovery route.</p><p>If saving fails, use the offered retry instead of repeating a purchase to force progress. The saved balance, inventory, ledger, quests, and world restoration must agree after relaunch. Checkpoint recovery need not restore the exact animation frame.</p><p>The full progression is Web3, then Blockchain, then AI. Completed worlds remain revisitable, and optional discoveries do not require full collection before progression. The smaller versioned demo quest list must report &quot;intro chapter complete&quot; rather than completion of the entire full game. An AI chapter is available only if its conditional scope is actually delivered.</p><p>The <a href="/Chainy-Docs/content/docs/user-guide.html">learner guide</a>, <a href="/Chainy-Docs/content/docs/design/app-flow.html">app flow</a>, and <a href="/Chainy-Docs/content/docs/game-design.html">GDD</a> supply the underlying rules.</p><h2 id="full-journey-and-curriculum">Full journey and curriculum<a class="header-anchor" href="#full-journey-and-curriculum" aria-label="Link to this section">​</a></h2><h3 id="later-quests">Later quests<a class="header-anchor" href="#later-quests" aria-label="Link to this section">​</a></h3><table><thead><tr><th>World</th><th>Retained full-design activities</th></tr></thead><tbody><tr><td>Web3</td><td>W05 exchanges coins for Builder Tokens; W06 invokes a conditional repair reward; W07 restores access with a protected fictional backup; W08 combines the concepts in a new harbor task</td></tr><tr><td>Blockchain</td><td>B04 updates a stale copy; B05 checks candidate transactions; B06 contrasts a bounded mining demonstration with validators; full B07 combines the broader chapter</td></tr><tr><td>AI</td><td>A01 labels and trains; A02 tests unfamiliar examples and revises; A03 uses a reserved final set; A04 verifies assistant advice; A05 supervises a proposed dispatch</td></tr></tbody></table><p>The proposed AI classifier uses synthetic requests labeled Routine or Review. Its output must depend on the learner&#39;s examples. A small nearest-neighbor classifier is a candidate design, not a confirmed implemented algorithm. Training, practice, and the first reserved-final test must stay separate. Authored assistant responses in A04 are a labeled simulation, not live generative AI or a trained classifier. The helper never spends automatically or promises that a request is safe.</p><h3 id="twelve-retained-concepts">Twelve retained concepts<a class="header-anchor" href="#twelve-retained-concepts" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Concept</th><th>Chainy example and delivery boundary</th></tr></thead><tbody><tr><td>Cryptocurrency</td><td>Fictional Chain Coin reward and spending in the core</td></tr><tr><td>Blockchain</td><td>Linked-record inspection and bounded repair in the core</td></tr><tr><td>Exchange</td><td>A later displayed swap into Builder Tokens</td></tr><tr><td>Gas fee</td><td>Separate 1-coin fee in the core purchase</td></tr><tr><td>Keys</td><td>Toy authorization and shareable address distinction in the core</td></tr><tr><td>Mining and validators</td><td>Later comparison of different network roles</td></tr><tr><td>NFT</td><td>Lantern #014 ownership, without claims of investment value or copyright transfer</td></tr><tr><td>Smart contract</td><td>Core purchase condition and later evidence-based repair claim</td></tr><tr><td>Token</td><td>Later issued Builder Tokens distinguished from native currency</td></tr><tr><td>Wallet</td><td>Core balance, activity, ownership display, and authorization</td></tr><tr><td>Seed phrase</td><td>Later protected game-only backup and recovery exercise</td></tr><tr><td>Node</td><td>Core reference copy and later stale-copy synchronization</td></tr></tbody></table><h3 id="a-z-expansion">A-Z expansion<a class="header-anchor" href="#a-z-expansion" aria-label="Link to this section">​</a></h3><p>The October 28 direction keeps all 26 original source terms, with 13 primary lessons in Web3 and 13 in Blockchain. The exact placements and formats below come from the grouping draft and remain proposals for review.</p><table><thead><tr><th>Proposed primary world</th><th>Original letter terms</th></tr></thead><tbody><tr><td>Web3</td><td>A Altcoins; C Cryptocurrency; E Exchanges; F Fiat Currency; H HODL; I Identity and Online Safety; J Jupiter (JUP); Q QR Codes in Web3; R Risks, Red Flags &amp; Staying Scam-Safe; U Understanding Web3 Safety; V Volatility; W Wallets; X XRP</td></tr><tr><td>Blockchain</td><td>B Blockchain; D Decentralization; G Gas Fees; K Keys; L Ledger; M Mining &amp; Validators; N NFTs; O On-Chain vs Off-Chain; P Proof Systems; S Smart Contracts; T Tokens; Y Your Data and Privacy in Web3; Z Zero-Knowledge Proofs</td></tr></tbody></table><p>The proposed 13 AI pairings use the same letter slots without replacing the original terms. They are A Artificial intelligence, B Bias, C Classification, D Dataset, F Feature, G Generative AI, H Human oversight, L Label, M Model, P Prediction, R Responsible AI, T Training, and V Validation. A paired term is a separate lesson, not another definition of the original Web3 term.</p><p>The grouping draft proposes six mini-game lessons and 20 quiz lessons for the original terms. The AI draft proposes four compact mini-game lessons and nine quizzes. These are content proposals, not implemented activity counts or beta requirements. Named real-world services and assets are examples, not endorsements or required accounts.</p><p>Standalone Wordle supports vocabulary practice. Its dictionary, allowed guesses, repeated-letter feedback, and attempt rules still need approved details. BlockMatch retains its own matching/cascade design and needs its own educational matching rule. Neither is interchangeable with the core ledger-repair exercise.</p><p>Source basis is the <a href="/Chainy-Docs/content/docs/planning/quest-curriculum.html">quest curriculum</a>, <a href="/Chainy-Docs/content/docs/planning/a-z-lesson-grouping-draft.html">letter grouping</a>, and <a href="/Chainy-Docs/content/docs/planning/a-z-ai-paired-lessons-draft.html">AI pairing draft</a>.</p><h2 id="visuals-interface-and-accessibility">Visuals, interface, and accessibility<a class="header-anchor" href="#visuals-interface-and-accessibility" aria-label="Link to this section">​</a></h2><p>The approved visual identity uses a blue-haired, yellow-clad Explorer and screen-faced robot guides. The three guides reuse the robot base. Compact low-poly islands and short routes keep the next objective visible. Landmarks, signs, and quest markers work together.</p><p>Dialogue appears over the live world, with text at the bottom, choices in the middle, and portraits on the sides. World input stops while dialogue or another modal activity is active. Purchase, save, loading, and error states need distinct feedback.</p><p>The quest log separates completed, current, locked, and optional objectives. The encyclopedia records Discovered, Explained, Practiced, and Demonstrated in a new situation. These labels describe evidence in the game; none means mastered.</p><p>The design requires readable text, touch controls that fit the reference phone, non-color selection cues, and instructions that work without audio. Tap-then-place is the intended alternative to dragging. The proposed 48 dp touch-target starting point and roughly 30 fps performance target are not measured compliance results.</p><p>Audio uses quiet ambience, readable confirmation cues, volume controls, and a silent-play path. Shipped audio and artwork need recorded ownership or license information. Generated concept images illustrate intentions and are not screenshots or import-ready Unity asset kits. See the <a href="/Chainy-Docs/content/docs/design/design-brief.html">art and UI brief</a>.</p><h2 id="technology-and-architecture">Technology and architecture<a class="header-anchor" href="#technology-and-architecture" aria-label="Link to this section">​</a></h2><h3 id="game-stack">Game stack<a class="header-anchor" href="#game-stack" aria-label="Link to this section">​</a></h3><p>The following versions are declarations in the local Unity project inspected November 9. An installed package does not prove the corresponding gameplay is implemented.</p><table><thead><tr><th>Technology</th><th>Declared version or role</th></tr></thead><tbody><tr><td>Unity Editor</td><td>6000.3.25f1</td></tr><tr><td>C#</td><td>Game code</td></tr><tr><td>SQLite binding</td><td><code>com.gilzoide.sqlite-net</code>, pinned Git package tag <code>1.3.3</code></td></tr><tr><td>Universal Render Pipeline</td><td><code>17.3.0</code></td></tr><tr><td>Input System</td><td><code>1.20.0</code></td></tr><tr><td>Cinemachine</td><td><code>3.1.7</code></td></tr><tr><td>AI Navigation</td><td><code>2.0.14</code></td></tr><tr><td>AI Inference</td><td><code>2.6.1</code>; package presence is not evidence of the educational classifier</td></tr><tr><td>uGUI</td><td><code>2.0.0</code></td></tr><tr><td>Newtonsoft JSON</td><td><code>3.2.2</code>; not a replacement for SQLite saves</td></tr><tr><td>Unity Test Framework</td><td><code>1.6.0</code></td></tr></tbody></table><p>The local checkout also includes Pixel Crushers Dialogue System, Joystick Pack, and Feel/Nice Vibrations assets. Their presence is source evidence, not a separate acceptance result.</p><p>The project also declares engine modules and editor integrations. Those declarations do not add multiplayer, online analytics, or other features to the approved product scope.</p><h3 id="architecture-boundaries">Architecture boundaries<a class="header-anchor" href="#architecture-boundaries" aria-label="Link to this section">​</a></h3><p>The current technical addendum directs UI actions through View, Handler, and Service. Views display state and collect input. Handlers translate player actions into service requests. Services own application behavior and use the database layer for storage. Typed events notify interested components, and ServiceRegistry supplies shared providers. UI does not own SQL.</p><p>The older technical design names Game Manager, Progress Manager, Database Manager, SceneLoader, input, dialogue, and activity managers. Those names describe responsibilities and are not a command to create duplicate systems. Actual implementation must follow the existing Unity project conventions. The older blanket event-command diagram is subordinate to the newer addendum.</p><p>In the inspected database startup path, DatabaseManager validates and snapshots authored ScriptableObjects on the main thread. A queued worker creates or updates the SQLite tables and synchronizes definitions by stable identifier. That content synchronization is separate from saving a learner&#39;s progress and does not establish versioned migration support.</p><p>Only one activity owns gameplay input at a time. A purchase confirmation must update its related records together, then report success. Repeated submission or retry must not repeat the economic effect. Blockchain repair must read the same saved purchase instead of creating an unrelated example transaction.</p><p>The <a href="/Chainy-Docs/content/docs/technical-design.html">technical design</a> and <a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">technical acceptance checklist</a> define these boundaries.</p><h2 id="local-data-and-offline-operation">Local data and offline operation<a class="header-anchor" href="#local-data-and-offline-operation" aria-label="Link to this section">​</a></h2><h3 id="current-source-mapping-versus-required-saves">Current source mapping versus required saves<a class="header-anchor" href="#current-source-mapping-versus-required-saves" aria-label="Link to this section">​</a></h3><p>The November 7 database review records <code>chainyApp.db</code> under Unity&#39;s <code>Application.persistentDataPath</code>. The inspected mapping has eight tables.</p><table><thead><tr><th>Table</th><th>Recorded purpose</th></tr></thead><tbody><tr><td><code>User</code></td><td>Local account, username, password hash, age, and creation time</td></tr><tr><td><code>Module</code></td><td>Authored subject module</td></tr><tr><td><code>Lesson</code></td><td>Authored lesson associated with a module</td></tr><tr><td><code>Lesson_Progress</code></td><td>Completion per user and lesson</td></tr><tr><td><code>Minigame</code></td><td>Authored minigame definition</td></tr><tr><td><code>minigame_progress</code></td><td>Best score and completion per user and minigame</td></tr><tr><td><code>Quest</code></td><td>Authored quest definition</td></tr><tr><td><code>Quest_Progress</code></td><td>Quest state per user and quest</td></tr></tbody></table><p>This mapping is not a database dump from an accepted APK. The source review did not establish explicit versioned migrations or the complete v2 save model. Local username/password code does not change the approved simple demo-profile flow.</p><p>The core requires profile separation, build/content/schema versions, quest and encyclopedia progress, balances, inventory, ledger records, reward receipts, restoration flags, and supported checkpoints. The required semantics are not approved SQL table names. Christian owns the schema changes and their recovery tests.</p><p>A committed purchase must not leave the coins deducted without the item, or the item granted without its ledger record. A failed save must preserve the last good checkpoint. Switching profiles must clear the previous profile&#39;s state before loading another. In-place app updates need explicit save-preservation tests.</p><h3 id="separate-offline-and-online-jobs">Separate offline and online jobs<a class="header-anchor" href="#separate-offline-and-online-jobs" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Job</th><th>Intended boundary</th></tr></thead><tbody><tr><td>Play and save</td><td>Entirely local after installation and any applicable later enrollment</td></tr><tr><td>Teacher enrollment</td><td>Later developer-issued voucher and one online activation</td></tr><tr><td>Learner pairing</td><td>Later offline pairing with a protected teacher workflow</td></tr><tr><td>Collection</td><td>Later approved record transfer from learner phones</td></tr><tr><td>Upload</td><td>Separate receipt-confirmed transfer to an approved restricted destination</td></tr><tr><td>Content update</td><td>Versioned content package with compatibility and interruption rules</td></tr><tr><td>App update</td><td>Signed APK with tested data preservation</td></tr><tr><td>Project management</td><td>Online team board, GitHub issue copies, and documentation site</td></tr></tbody></table><p>JSON may be an export format. SQLite does not synchronize, upload, or back up records by itself. Nearby Connections and local Wi-Fi remain transport candidates, not verified implementations. The later 20-40-phone use case is a design scenario, not proven simultaneous capacity.</p><p>Participant identities, identity maps, raw learner records, credentials, and signing keys stay outside repositories and issues. The authorized custodian keeps any permitted identity mapping in restricted storage. An attempted export must not delete local records. Game-only wallet recovery does not restore an unsynced lost phone.</p><p>See the <a href="/Chainy-Docs/content/docs/design/database-schema.html">database reference</a> and <a href="/Chainy-Docs/content/docs/offline-data-plan.html">offline-data plan</a>.</p><h2 id="set-up-and-run-the-game">Set up and run the game<a class="header-anchor" href="#set-up-and-run-the-game" aria-label="Link to this section">​</a></h2><h3 id="locations-and-prerequisites">Locations and prerequisites<a class="header-anchor" href="#locations-and-prerequisites" aria-label="Link to this section">​</a></h3><p>The game source is separate from this management repository. The documented remote is <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Kamiyon-Studio/Chainy-Game</a>. The inspected local checkout is <code>O:\\Documents\\Unity Projects\\ChainyApp</code>. This management checkout is <code>O:\\Documents\\GitHub\\Chainy</code>. These are this workstation&#39;s paths, not required paths for every teammate. The local game checkout uses Plastic SCM and contains <code>.plastic</code>, not <code>.git</code>. Record its actual changeset identifier rather than inventing a Git commit for the local build.</p><p>Use the project&#39;s pinned Unity version instead of upgrading it during setup. The following is a setup procedure to verify, not a claim that a build was run for this handbook.</p><ol><li>Obtain the current game checkout and record its revision from Christian.</li><li>Install Unity Hub and Unity Editor <code>6000.3.25f1</code>.</li><li>Include Android Build Support and its SDK, NDK, and OpenJDK modules.</li><li>Add the folder containing <code>Assets</code>, <code>Packages</code>, and <code>ProjectSettings</code> to Unity Hub.</li><li>Open the project and allow its declared packages to resolve.</li><li>Check the Unity Console for compilation and import errors.</li><li>Open <code>Assets/Scenes/MainMenu.unity</code> and press Play.</li><li>Verify the actual available flow with synthetic local data.</li></ol><p>First-time editor/package installation can need internet access. Git must be available for the Git-pinned SQLite package to resolve. That setup requirement is separate from offline gameplay on an installed device. No wallet account, cloud AI API key, or public blockchain connection is required for the core design.</p><p>The inspected editor input bindings use WASD or arrow keys for movement, E for interaction, Space for dialogue continuation, and Escape for pause. The input asset also declares J for the quest log, but a binding alone does not establish a working journal. Mobile source includes a floating joystick, contextual interaction, and tap-to-continue dialogue.</p><p>The current startup menu opens local login UI. In the inspected <code>LoginUI.cs</code>, success updates a feedback label without a visible call to open the main menu or world selection. The menu, level cards, and world-loading components exist separately, but their complete click path remains unverified. Record a blocked transition for Christian instead of assuming that sign-in reaches the designed chapter.</p><p>Use <strong>Window &gt; General &gt; Test Runner</strong> for Unity EditMode and PlayMode checks when applicable tests exist. The separate database-test README names a <code>.csproj</code> that was absent in the inspected checkout. Its zero-quest expectation also conflicts with the current one-quest configuration. That documented standalone test command must be repaired before it can provide verification.</p><h3 id="android-installation-and-device-target">Android installation and device target<a class="header-anchor" href="#android-installation-and-device-target" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Setting or evidence</th><th>Current meaning</th></tr></thead><tbody><tr><td>Minimum installable SDK</td><td>API 25, confirmed policy and local project setting</td></tr><tr><td>Required reference test</td><td>Android 10, API 29</td></tr><tr><td>Reference RAM</td><td>4 GB physical RAM</td></tr><tr><td>Reference storage</td><td>128 GB total device capacity, not required free space</td></tr><tr><td>Reported processor</td><td>2.3 GHz octa-core</td></tr><tr><td>Device evidence label</td><td>&quot;vivo 2019&quot;, Funtouch OS 10; no more specific retail model inferred</td></tr><tr><td>ABI and graphics</td><td>ARM64 and OpenGL ES 3.2 or Vulkan 1.1 are provisional targets pending device verification</td></tr><tr><td>Performance</td><td>Around 30 fps is a proposed target, not a measured result</td></tr></tbody></table><p>For a development build, use <strong>File &gt; Build Profiles</strong>, select Android, verify the intended scenes and settings, and produce a named APK. The inspected enabled scene order is MainMenu, LoadingScene, Web3WorldScene, BlockchainWorldScene, and AIWorldScene. The manual Test scene is excluded. The local settings declare ARM64, IL2CPP, automatic target SDK, app version <code>0.1.0</code>, and Android version code <code>1</code>. These are source settings, not verified release metadata or proof of device support. Christian must confirm the final application identifier and signing configuration for the candidate. Record the source revision, Unity version, content version, build identifier, and non-sensitive device details. Use the required reference phone for installation, launch, offline play, and save/relaunch checks. Editor success and installation on API 25 do not establish reference-device acceptance.</p><p>For a learner session, obtain the specific APK approved by Christian and follow its accompanying installation instructions. If Android requires installation permission for the chosen transfer method, enable only the permission needed for that installation. Use synthetic demo profiles for internal checks. Disconnect networking before the offline demonstration and verify the completed state after relaunch.</p><p>This handbook supplies no APK download because no candidate was verified for it. Do not uninstall or clear app data as a routine fix when records need preservation. Signing keys and passwords belong outside the repository. See the <a href="/Chainy-Docs/content/docs/hardware-validation.html">hardware validation plan</a>.</p><h2 id="documentation-and-team-tools">Documentation and team tools<a class="header-anchor" href="#documentation-and-team-tools" aria-label="Link to this section">​</a></h2><p>The documentation viewer and board are management tools. Their availability does not affect the intended offline game loop.</p><p>The <a href="https://owenlim225.github.io/Chainy-Docs/board/">team board</a> is the editing interface for cards, dates, named history, and handoffs. Use your assigned individual account and private password. Teammates do not need GitHub accounts to update the board. Credentials are deliberately omitted from this handbook.</p><p>Use Board for cards and Timeline for the Gantt view. Open a card to read its owner, prerequisites, completion check, evidence, and history. Record actual progress and blockers, then change status when the card&#39;s completion check is met. Create a separate handoff card when another role must continue the work.</p><p>GitHub issues receive queued copies of board changes. Do not independently edit managed issue bodies or old Project fields. <code>docs/backlog.json</code> is the publication snapshot, not a second editing interface. Trello is retired. Reference links can become public through issue copies, so they must not contain participant records, secrets, or private signed URLs.</p><h3 id="run-the-documentation-viewer-locally">Run the documentation viewer locally<a class="header-anchor" href="#run-the-documentation-viewer-locally" aria-label="Link to this section">​</a></h3><p>The viewer README specifies Node 24, npm, VitePress, Vue, Markdown tooling, and Mermaid. These are documentation dependencies, not dependencies installed on learner phones. From this workstation, the development command sequence is:</p><pre><code class="language-powershell"><span class="hljs-built_in">Set-Location</span> <span class="hljs-string">&#39;O:\\Documents\\GitHub\\Chainy\\tools\\docs-viewer&#39;</span>
npm ci
npm run dev
</code></pre><p>Use the local address printed by VitePress. The package script prepares the documents before starting the viewer. Its production validation command is <code>npm run build</code>, and its unit-test command is <code>npm test</code>. The optional search check is <code>npm run test:search</code>. Editing source Markdown does not publish the public site.</p><p>The repository also has board synchronization and deployment tooling. The board combines a static browser interface with a Cloudflare Worker and a SQLite Durable Object for staff accounts, cards, history, and the retry queue. This server-side SQLite store is separate from the game&#39;s on-device SQLite database. Maintainers can run <code>npm ci</code>, <code>npm run check</code>, and <code>npm test</code> from <code>tools/kanban-sync</code>. <code>npm run deploy:check</code> is its deployment dry run, not a deployment. Those tools are for the responsible maintainer, not prerequisites for reading this guide or playing the game. Use the <a href="/Chainy-Docs/content/tools/docs-viewer/readme.html">viewer README</a>, <a href="/Chainy-Docs/content/tools/kanban-sync/readme.html">sync README</a>, and <a href="/Chainy-Docs/content/docs/team-board-guide.html">board guide</a> for their current operational details.</p><h2 id="team-responsibilities">Team responsibilities<a class="header-anchor" href="#team-responsibilities" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Person</th><th>Responsibility lane</th><th>Typical handoff</th></tr></thead><tbody><tr><td>Sherwin Limosnero</td><td>Project coordination and game-design decisions</td><td>Approved scope, mechanics, and session arrangements</td></tr><tr><td>Christian Jude Villaber</td><td>Game code, data, builds, and technical integration</td><td>Named builds, technical contracts, and test evidence</td></tr><tr><td>Luis Cabrido III</td><td>Art assets</td><td>Importable assets with required specifications and licenses</td></tr><tr><td>Sean Matthew Narvaez</td><td>All authored project documentation</td><td>Approved lesson copy, manuscript, guides, and evidence records</td></tr><tr><td>Miguel De Leon</td><td>Game UI implementation</td><td>Working screens, feedback, and interaction states</td></tr></tbody></table><p>Each card has one named owner in one lane. Review or technical input does not create a second owner. Cross-role dependencies use explicit handoff cards. This handbook is prepared at the user&#39;s request; Sean remains the project&#39;s documentation owner.</p><p>The handoff must say what the receiving person can use and how it is checked. For example, a build handoff needs an identifiable APK and revision, while an art handoff needs usable files rather than only a concept image. The <a href="/Chainy-Docs/content/docs/team-delegation.html">team-delegation guide</a> contains the fuller role descriptions.</p><h2 id="testing-and-acceptance">Testing and acceptance<a class="header-anchor" href="#testing-and-acceptance" aria-label="Link to this section">​</a></h2><p>Specifications describe required results. Only executed checks against a named artifact establish acceptance. Every result needs the build revision, device, steps, expected result, actual result, tester, and appropriate evidence.</p><table><thead><tr><th>Test area</th><th>Required observation</th></tr></thead><tbody><tr><td>Installation and offline start</td><td>The named APK installs and launches on the reference phone without a gameplay network dependency</td></tr><tr><td>Movement and dialogue</td><td>Nearby interaction works; modal UI stops movement; closing restores input</td></tr><tr><td>Economy</td><td>Reward 12 once, spend 8 plus 1, retain 3, own the lantern, and equip for free</td></tr><tr><td>Cancellation and duplicate input</td><td>Cancellation is free; repeated taps and retries do not duplicate charges or rewards</td></tr><tr><td>Restoration</td><td>Workshop and beacon state match completed quests after relaunch</td></tr><tr><td>Blockchain repair</td><td>Same saved purchase, three linked blocks, trusted checkpoint, and rejection of altered 6 versus original 8</td></tr><tr><td>Persistence</td><td>Related records agree after success, failure, interruption, and repeat save</td></tr><tr><td>Profiles</td><td>Two synthetic profiles remain separate through switching and relaunch</td></tr><tr><td>Recovery and updates</td><td>Safe error feedback, checkpoint recovery, and save-preserving signed update</td></tr><tr><td>Interface</td><td>Readable text, non-color cues, usable touch controls, and silent-play instructions</td></tr><tr><td>Conditional AI</td><td>Predictions depend on examples; practice and first reserved-final evidence stay separate</td></tr></tbody></table><p>Measure loading, sustained performance, memory, heat, storage use, and suspend/resume behavior on the actual phone. Do not replace measurements with processor specifications or a desktop screenshot. No such performance measurements were made for this handbook.</p><p>Use <a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">V2-R01-V2-R12</a>, the GDD&#39;s GP checks, and the <a href="/Chainy-Docs/content/docs/qa-evaluation.html">QA plan</a> for traceability. Deferred Wordle, BlockMatch, and teacher services are not core beta blockers. Missing core save integrity is a blocker even when the scene looks complete.</p><h2 id="schedule-and-capstone-evidence">Schedule and capstone evidence<a class="header-anchor" href="#schedule-and-capstone-evidence" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Date</th><th>Recorded purpose</th></tr></thead><tbody><tr><td>November 9, 2026</td><td>Build go/no-go and candidate readiness</td></tr><tr><td>November 10, 2026</td><td>Cryptita Plays community session; accepted gameplay beta or labeled concept/prototype feedback</td></tr><tr><td>November 11-13</td><td>Actual findings, retested fixes, and evidence analysis</td></tr><tr><td>November 14-16</td><td>Manuscript and evidence package</td></tr><tr><td>November 17-20</td><td>Defense rehearsal, recovery drill, and release freeze</td></tr><tr><td>November 21, 2026</td><td>Fixed pre-final</td></tr></tbody></table><p>Earlier October implementation windows were planning targets, not proof that the work finished on those dates. Later board dates for deferred scope are provisional planning windows, not promised releases. The GDD&#39;s 95-153 focused core hours and 20-35 optional AI hours are estimates, not measured effort or remaining-work estimates. Reported 16-18-hour daily availability is not a sustainable productivity assumption. Preserve integration, QA, manuscript, and rehearsal time.</p><p>The pre-final requires functional core modules, completed manuscript formatting and chapters, and the required pilot-area evidence/documents. The manuscript includes introduction, related literature, design and methodology, results and discussion, conclusions and recommendations, references, and appendices. Appendices cover source extracts, evaluation tools, sample inputs/outputs, user guide, flows, screen layouts, tests, authorized data-gathering evidence, CVs, letters/certification, UAT, and MOU as required.</p><p>The school&#39;s completion formula, eight unnamed quality criteria, and exact &quot;ISO 2010&quot; instrument remain unresolved in the current baseline. Task counts cannot establish the school&#39;s required percentage. Cryptita Plays community feedback is not automatically approved school pilot evidence. Participant permissions, instruments, sample, custodian, and accepted analysis must be confirmed through the responsible people. No results, approvals, or identities may be invented.</p><p>See the <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">current task plan</a> and <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">manuscript evidence map</a>.</p><h2 id="common-questions-and-troubleshooting">Common questions and troubleshooting<a class="header-anchor" href="#common-questions-and-troubleshooting" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Question or symptom</th><th>Answer or next action</th></tr></thead><tbody><tr><td>Is Chainy a real crypto application?</td><td>No. Currency, addresses, authorization, and ledger interactions are educational simulations.</td></tr><tr><td>Does the player need internet?</td><td>The intended installed gameplay and saves are offline. Setup, later activation, transfer, updates, and project tools are separate jobs.</td></tr><tr><td>Is AI already working?</td><td>Package presence does not establish that. The small classifier is conditional stretch, and runtime acceptance is unverified here.</td></tr><tr><td>Why is AI unavailable in a core demo?</td><td>A01-A03 is admitted only after the core passes. It must not be presented as completed through concept art.</td></tr><tr><td>Is Blockchain repair BlockMatch?</td><td>No. They are separate activities with separate rules.</td></tr><tr><td>Does a learner code recover another phone?</td><td>No. It is neither authentication nor cross-device backup.</td></tr><tr><td>Does a restored workshop prove learning?</td><td>It proves completion only when the build actually performs it. Learning requires appropriate evidence beyond completion.</td></tr><tr><td>Unity import or compile fails</td><td>Check the pinned editor version, declared packages, and Console errors. Record the exact error for Christian before changing versions.</td></tr><tr><td>The current game shows local account screens</td><td>Source implementation and the approved beta flow differ. Record that mismatch; do not describe the account screen as the intended demo-profile flow.</td></tr><tr><td>Login or startup never finishes</td><td>Preserve logs and synthetic reproduction steps. The November 7 review identified a database-startup-failure risk, but the current cause needs verification.</td></tr><tr><td>A save fails or progress appears wrong</td><td>Avoid clearing data. Preserve the last good state and report build, profile, action, and observed result to Christian.</td></tr><tr><td>The APK will not install</td><td>Capture the install error and check the build, SDK policy, ABI, storage, and signing compatibility. Do not erase an existing installation to bypass an unexplained failure.</td></tr><tr><td>A document disagrees with this guide</td><td>Prefer direct owner decisions and the current baseline, then the canonical GDD and actual evidence. Report the discrepancy rather than silently changing scope.</td></tr></tbody></table><h2 id="open-decisions-and-source-map">Open decisions and source map<a class="header-anchor" href="#open-decisions-and-source-map" aria-label="Link to this section">​</a></h2><p>The following facts still need current evidence or owner confirmation.</p><ul><li>Christian supplies the candidate revision, reproducible APK, actual startup/build configuration, and reference-device results.</li><li>Christian verifies the full v2 persistence contract, profile switching, incomplete-progress updates, startup failure handling, and versioned recovery.</li><li>Sherwin records the November 9 go/no-go and reconfirms community arrangements.</li><li>Sherwin approves detailed content and any replacement design before it supersedes GDD v2.</li><li>Sean finalizes player instructions against the tested build and records the school&#39;s evidence requirements.</li><li>AI inclusion requires core pass evidence, approved classifier data/features, and capacity approval.</li><li>Device ABI, graphics support, performance, install footprint, and save-preserving updates require measurement.</li></ul><p>This guide preserves the current decisions rather than resolving these questions by assumption. Its local source references describe a static snapshot and can become outdated as development continues.</p><table><thead><tr><th>Source</th><th>Authority or use</th></tr></thead><tbody><tr><td><a href="/Chainy-Docs/content/docs/project-baseline.html">Project baseline</a></td><td>Current decisions and dated implementation evidence</td></tr><tr><td><a href="/Chainy-Docs/content/docs/game-design.html">Canonical GDD</a></td><td>Gameplay, quests, teaching examples, and full-design boundaries</td></tr><tr><td><a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">Task plan</a></td><td>Delivery gates and timeline</td></tr><tr><td><a href="/Chainy-Docs/content/docs/documentation-index.html">Documentation index</a></td><td>Complete project-document navigation</td></tr><tr><td><a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">Product requirements</a></td><td>V2 acceptance requirements</td></tr><tr><td><a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">Technical requirements</a></td><td>Technical acceptance boundaries</td></tr><tr><td><a href="/Chainy-Docs/content/docs/technical-design.html">Technical design</a></td><td>Architecture and integration addendum</td></tr><tr><td><a href="/Chainy-Docs/content/docs/design/database-schema.html">Database reference</a></td><td>Dated source mapping and required persistence semantics</td></tr><tr><td><a href="/Chainy-Docs/content/docs/offline-data-plan.html">Offline-data plan</a></td><td>Gameplay, enrollment, transfer, and privacy boundaries</td></tr><tr><td><a href="/Chainy-Docs/content/docs/hardware-validation.html">Hardware validation</a></td><td>Device evidence and checks</td></tr><tr><td><a href="/Chainy-Docs/content/docs/qa-evaluation.html">QA and evaluation</a></td><td>Test and learner-evidence procedure</td></tr><tr><td><a href="/Chainy-Docs/content/docs/user-guide.html">Learner guide</a></td><td>Draft player/session instructions</td></tr><tr><td><a href="/Chainy-Docs/content/docs/learning-foundations.html">Learning foundations</a></td><td>Teaching and assessment distinctions</td></tr><tr><td><a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">Manuscript evidence map</a></td><td>School deliverables and unresolved requirements</td></tr><tr><td><a href="/Chainy-Docs/content/docs/team-delegation.html">Team delegation</a></td><td>Role ownership and handoffs</td></tr><tr><td><a href="/Chainy-Docs/content/docs/team-board-guide.html">Team board guide</a></td><td>Card editing and named history</td></tr><tr><td>Local game <code>ProjectSettings/ProjectVersion.txt</code></td><td>Unity version inspected November 9</td></tr><tr><td>Local game <code>Packages/manifest.json</code></td><td>Declared package versions inspected November 9</td></tr><tr><td>Local game <code>AGENTS.md</code> and <code>ProjectSettings/EditorBuildSettings.asset</code></td><td>Startup, source-control convention, and enabled scenes</td></tr><tr><td>Local game <code>Assets/Scripts/Features/UI/MainMenuUI/LoginUI.cs</code></td><td>Static login-transition limitation</td></tr><tr><td>Local game <code>Assets/_Assets/ScriptableObjects/db/config/DatabaseData.asset</code></td><td>Serialized content counts</td></tr></tbody></table><p>This file is a documentation deliverable. It does not certify a working build, publish a site, approve research, or change the adopted scope.</p></div>`,1)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
